func inRanges(r rune, rs []runeRange) bool {
	i := sort.Search(len(rs), func(i int) bool { return rs[i].hi >= r })
	return i < len(rs) && rs[i].lo <= r
}

func isNameStart(r rune) bool {
	if r < 0x80 {
		return r == ':' || r == '_' || 'A' <= r && r <= 'Z' || 'a' <= r && r <= 'z'
	}
	return inRanges(r, nameStartRanges[:])
}

func isNameRest(r rune) bool {
	if r < 0x80 {
		return isNameStart(r) || r == '-' || r == '.' || '0' <= r && r <= '9'
	}
	return inRanges(r, nameRestRanges[:])
}
